import itertools
n=6
for p in itertools.permutations(range(n)):
    seen=set(); ok=True
    for c1 in range(n):
        for c2 in range(c1+1,n):
            v=(c2-c1,p[c2]-p[c1])
            if v in seen:
                ok=False; break
            seen.add(v)
        if not ok: break
    if ok:
        print(p)
        raise SystemExit
